<template>
  <section class="page">
    <header class="page-header"><div><h1>Báo cáo nội dung</h1><p class="subtitle">Xem xét báo cáo truyện và chương từ độc giả.</p></div><button class="button" :disabled="loading" @click="load">Tải lại</button></header>
    <form class="filters" @submit.prevent="applyFilters">
      <label>Trạng thái<select v-model="status"><option value="">Tất cả</option><option value="0">Chờ xử lý</option><option value="1">Đã chấp nhận</option><option value="2">Đã từ chối</option></select></label>
      <label>Loại nội dung<select v-model="targetType"><option value="">Tất cả</option><option value="1">Truyện</option><option value="2">Chương</option></select></label>
      <button class="button primary" :disabled="loading">Lọc</button>
    </form>
    <div v-if="message" class="notice" :class="{error: messageIsError}" role="status">{{ message }} <button v-if="messageIsError" class="link-button" @click="load">Thử lại</button></div>
    <div class="card">
      <div v-if="loading && !items.length" class="empty">Đang tải báo cáo…</div><div v-else-if="!items.length" class="empty">Không có báo cáo phù hợp.</div>
      <div v-else class="table-wrap"><table class="data-table"><thead><tr><th>Nội dung</th><th>Người gửi</th><th>Lý do</th><th>Trạng thái</th><th>Ngày gửi</th><th></th></tr></thead><tbody>
        <tr v-for="item in items" :key="item.reportId" :data-report-id="item.reportId"><td><strong>{{ item.targetTitle }}</strong><br><small>{{ typeLabel(item.targetType) }}<span v-if="item.targetUnavailable"> · Đã ẩn/xóa</span></small></td><td>{{ item.reporterName }}<br><small>{{ item.reporterEmail }}</small></td><td>{{ reasonLabel(item.reason) }}</td><td><span class="status" :class="statusClass(item.status)">{{ statusLabel(item.status) }}</span></td><td>{{ formatDate(item.createdAt) }}</td><td><button class="button" @click="selected=item">Xem</button></td></tr>
      </tbody></table></div><AdminPager :page="page" :page-size="pageSize" :total="total" :busy="loading" @change="changePage" />
    </div>
    <div v-if="selected" class="modal-backdrop" @click.self="closeDetail"><section class="modal" role="dialog" aria-modal="true"><h2>{{ selected.targetTitle }}</h2><dl class="detail-grid"><dt>Loại</dt><dd>{{ typeLabel(selected.targetType) }}</dd><dt>Người gửi</dt><dd>{{ selected.reporterName }} · {{ selected.reporterEmail }}</dd><dt>Lý do</dt><dd>{{ reasonLabel(selected.reason) }}</dd><dt>Mô tả báo cáo</dt><dd>{{ selected.description || 'Không có mô tả thêm.' }}</dd><dt>Tình trạng</dt><dd>{{ selected.targetUnavailable ? 'Đã ẩn hoặc xóa mềm' : 'Đang công khai' }}</dd></dl><div v-if="selected.targetContent" class="content-preview">{{ selected.targetContent }}</div><div class="actions" style="margin-top:18px"><button class="button" @click="closeDetail">Đóng</button><template v-if="selected.status===0"><button class="button danger" @click="openDecision(true)">Chấp nhận và ẩn</button><button class="button primary" @click="openDecision(false)">Từ chối báo cáo</button></template></div></section></div>
    <div v-if="decision" class="modal-backdrop" @click.self="closeDecision"><section class="modal compact" role="dialog" aria-modal="true"><h2>{{ decision.accept ? 'Chấp nhận báo cáo' : 'Từ chối báo cáo' }}</h2><p v-if="decision.accept"><strong>{{ selected.targetTitle }}</strong> sẽ bị ẩn. {{ selected.targetType===1 ? 'Các chương của truyện cũng không còn truy cập công khai.' : 'Các chương khác vẫn đọc được.' }}</p><p v-else>Nội dung sẽ được giữ nguyên.</p><label class="field">Ghi chú xử lý<textarea v-model="resolutionNote" maxlength="1000" :disabled="submitting"></textarea></label><div v-if="decisionError" class="notice error">{{ decisionError }}</div><div class="actions modal-actions"><button class="button" :disabled="submitting" @click="closeDecision">Hủy</button><button class="button" :class="decision.accept?'danger':'primary'" :disabled="submitting" @click="submitDecision">{{ submitting ? 'Đang xử lý…' : 'Xác nhận' }}</button></div></section></div>
  </section>
</template>
<script setup>
import { onMounted, ref } from 'vue';import { contentReportsApi } from '../api/adminApi';import { apiMessage } from '../services/apiError';import AdminPager from '../components/AdminPager.vue'
const items=ref([]),page=ref(1),pageSize=ref(10),total=ref(0),status=ref('0'),targetType=ref(''),loading=ref(false),message=ref(''),messageIsError=ref(false),selected=ref(null),decision=ref(null),resolutionNote=ref(''),decisionError=ref(''),submitting=ref(false)
async function load(){loading.value=true;message.value='';try{const{data}=await contentReportsApi.list({page:page.value,pageSize:pageSize.value,status:status.value===''?null:Number(status.value),targetType:targetType.value===''?null:Number(targetType.value)});items.value=data.items||[];total.value=data.totalItems||0;if(!items.value.length&&page.value>1){page.value--;await load()}}catch(e){message.value=apiMessage(e,'Không tải được báo cáo.');messageIsError.value=true}finally{loading.value=false}}
function applyFilters(){page.value=1;load()}function changePage(value){page.value=value;load()}function closeDetail(){if(!submitting.value)selected.value=null}function openDecision(accept){decision.value={accept};decisionError.value='';resolutionNote.value=''}function closeDecision(){if(!submitting.value)decision.value=null}
async function submitDecision(){if(submitting.value)return;submitting.value=true;decisionError.value='';try{await contentReportsApi.decide(selected.value.reportId,decision.value.accept,resolutionNote.value.trim()||null);decision.value=null;selected.value=null;await load();message.value='Đã xử lý báo cáo và cập nhật nội dung.';messageIsError.value=false}catch(e){if(e.response?.status===409){decision.value=null;selected.value=null;await load();message.value='Báo cáo đã được quản trị viên khác xử lý. Danh sách đã tải lại.';messageIsError.value=false}else decisionError.value=apiMessage(e,'Không xử lý được báo cáo.')}finally{submitting.value=false}}
const reasons={1:'Nội dung không phù hợp',2:'Vi phạm bản quyền',3:'Thông tin sai lệch',4:'Spam hoặc quảng cáo',5:'Lý do khác'};const reasonLabel=v=>reasons[v]||`Lý do ${v}`;const typeLabel=v=>v===1?'Truyện':'Chương';const statusLabel=v=>['Chờ xử lý','Đã chấp nhận','Đã từ chối'][v]||'Không rõ';const statusClass=v=>v===0?'pending':v===1?'approved':'rejected';const formatDate=v=>new Intl.DateTimeFormat('vi-VN',{dateStyle:'short',timeStyle:'short'}).format(new Date(v));onMounted(load)
</script>
